function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.counterparty || !body.offerId) {
    return [dspNegotiationError(422, 'invalid_request', ['counterparty and offerId are required'], null, body.consumerPid), null];
}
const now = new Date().toISOString();
const negId = 'neg-' + crypto.randomBytes(6).toString('hex');
const agrId = 'agr-' + crypto.randomBytes(6).toString('hex');

const counterparty = (msg.identity && msg.identity.did) ? msg.identity.did : body.counterparty;
const negotiation = {
    id: negId,
    providerPid: negId,
    consumerPid: body.consumerPid || negId,
    state: 'FINALIZED',
    agreementId: agrId,
    offerId: body.offerId,
    counterparty: counterparty,
    createdAt: now,
    updatedAt: now
};

const negs = global.get('negotiations') || {};
negs[negId] = negotiation;
global.set('negotiations', negs);

node.log('Negotiation ' + negId + ' auto-finalised → agreement ' + agrId);

msg.payload = { negotiationId: negId };
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 202;
return [msg, { payload: '' }];

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

const negs = global.get('negotiations') || {};
const id = msg.req.params.id;
const found = negs[id];
if (!found) {
    dspNegotiationError(404, 'not_found', ['Negotiation ' + id + ' not found'], id, id);
} else {
    msg.statusCode = 200;
    msg.payload = found;
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

const negs = global.get('negotiations') || {};
const id = msg.req.params.id;
const neg = negs[id];
if (!neg) {
    dspNegotiationError(404, 'not_found', ['Negotiation ' + id + ' not found'], id, id);
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null];
}
const now = new Date().toISOString();
const terminated = Object.assign({}, neg, { state: 'TERMINATED', updatedAt: now });
negs[id] = terminated;
global.set('negotiations', negs);

msg.payload = terminated;
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return [msg, { payload: '' }];
